// src/context/BooksContext.jsx
import { createContext, useContext, useState, useEffect, useCallback } from "react";
import { getBooks, createBook, deleteBook as apiDelete, updateBook as apiUpdate } from "../services/bookService";
import { MOCK_BOOKS } from "../utils/mockData";

const BooksContext = createContext(null);
const BOOK_LINKS_STORAGE_KEY = "books_read_links_by_id";

const readStoredLinks = () => {
  try {
    const raw = localStorage.getItem(BOOK_LINKS_STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
};

const writeStoredLinks = (value) => {
  try {
    localStorage.setItem(BOOK_LINKS_STORAGE_KEY, JSON.stringify(value));
  } catch {
    // Ignore localStorage write failures.
  }
};
const normalizeUrl = (url) => {
  const value = (url || "").trim();
  if (!value) return "";
  if (/^https?:\/\//i.test(value)) return value;
  return `https://${value}`;
};

const normalizeBook = (book) => ({
  ...book,
  readLink: normalizeUrl(
    book.readLink ||
      book.read_link ||
      book.link ||
      book.Link ||
      book.book_url ||
      book.url ||
      ""
  ),
});

const mergeBookWithStoredLink = (book, storedLinks) => {
  const storedLink = normalizeUrl(storedLinks[String(book.id)] || "");
  if (book.readLink || !storedLink) return book;
  return { ...book, readLink: storedLink };
};

export function BooksProvider({ children }) {
  const [books, setBooks]     = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchBooks = useCallback(async (params = {}) => {
    setLoading(true);
    try {
      const res = await getBooks(params);
      const storedLinks = readStoredLinks();
      setBooks(
        (res.data.books || [])
          .map(normalizeBook)
          .map((book) => mergeBookWithStoredLink(book, storedLinks))
      );
    } catch {
      // Fallback to mock data if API not reachable
      const storedLinks = readStoredLinks();
      setBooks(
        MOCK_BOOKS
          .map(normalizeBook)
          .map((book) => mergeBookWithStoredLink(book, storedLinks))
      );
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchBooks(); }, [fetchBooks]);

  async function addBook(data) {
    const res = await createBook(data);
    // Some backends don't echo link fields in create response.
    const createdBook = normalizeBook({ ...(res.data.book || {}), ...data });
    if (createdBook.id && createdBook.readLink) {
      const storedLinks = readStoredLinks();
      storedLinks[String(createdBook.id)] = createdBook.readLink;
      writeStoredLinks(storedLinks);
    }
    setBooks((prev) => [createdBook, ...prev]);
    return createdBook;
  }

  async function deleteBook(id) {
    await apiDelete(id);
    const storedLinks = readStoredLinks();
    delete storedLinks[String(id)];
    writeStoredLinks(storedLinks);
    setBooks((prev) => prev.filter((b) => b.id !== id));
  }

  async function updateBook(id, data) {
    const res = await apiUpdate(id, data);
    const updatedBook = normalizeBook(res.data.book);
    setBooks((prev) => prev.map((b) => (b.id === id ? updatedBook : b)));
  }

  return (
    <BooksContext.Provider value={{ books, loading, fetchBooks, addBook, deleteBook, updateBook }}>
      {children}
    </BooksContext.Provider>
  );
}

export function useBooks() {
  const ctx = useContext(BooksContext);
  if (!ctx) throw new Error("useBooks must be inside BooksProvider");
  return ctx;
}
